import React from "react";
import "./../css/form.css";
import moment from "moment-jalaali";
import {
  FaUser,
  FaPhone,
  FaMapMarkerAlt,
  FaImage,
  FaTag,
  FaQuestionCircle,
  FaClock,
  FaLink,
} from "react-icons/fa";

class CustomerRequestForm extends React.Component {
  constructor(props) {
    super(props);

    this.state = {
      fullName: "",
      mobile: "",
      landline: "",

      province: "",
      city: "",
      address: "",

      deviceType: "",
      deviceBrand: "",

      deviceIssue: "",
      visitTime: "",
      description: "",

      states: [],
      cities: [],
      types: [],
      brands: [],

      loadingStates: false,
      loadingCities: false,
      loadingTypesBrands: false,
      submitting: false,
    };

    this.handleChange = this.handleChange.bind(this);
    this.handleSubmit = this.handleSubmit.bind(this);
    this.loadStates = this.loadStates.bind(this);
    this.loadCities = this.loadCities.bind(this);
    this.loadTypesBrands = this.loadTypesBrands.bind(this);
  }

  componentDidMount() {
    this.loadStates();
    this.loadTypesBrands();
  }

  handleChange(field) {
    return (e) => {
      const value = e.target.value;

      this.setState({
        [field]: value,
      });

      if (field === "province") {
        this.setState({
          city: "",
          cities: [],
        });

        if (value) {
          this.loadCities(value);
        }
      }
    };
  }

  loadStates() {
    const token = localStorage.getItem("token");

    this.setState({
      loadingStates: true,
    });

    fetch("https://iranaserviceapp.ir/test/api/cities", {
      method: "GET",
      headers: {
        Accept: "application/json",
        ...(token
          ? {
              Authorization: `Bearer ${token}`,
            }
          : {}),
      },
    })
      .then((response) => response.json())
      .then((data) => {
        if (data.status === "1") {
          this.setState({
            states: data.states || [],
            loadingStates: false,
          });
        } else {
          this.setState({
            loadingStates: false,
          });
        }
      })
      .catch((error) => {
        console.error("loadStates error:", error);

        this.setState({
          loadingStates: false,
        });
      });
  }

  loadCities(stateId) {
    const token = localStorage.getItem("token");

    this.setState({
      loadingCities: true,
      cities: [],
      city: "",
    });

    fetch(
      `https://iranaserviceapp.ir/test/api/cities?id=${encodeURIComponent(
        stateId
      )}`,
      {
        method: "GET",
        headers: {
          Accept: "application/json",
          ...(token
            ? {
                Authorization: `Bearer ${token}`,
              }
            : {}),
        },
      }
    )
      .then((response) => response.json())
      .then((data) => {
        if (data.status === "1") {
          this.setState({
            cities: data.cities || [],
            loadingCities: false,
          });
        } else {
          this.setState({
            cities: [],
            loadingCities: false,
          });
        }
      })
      .catch((error) => {
        console.error("loadCities error:", error);

        this.setState({
          cities: [],
          loadingCities: false,
        });
      });
  }

  loadTypesBrands() {
    const token = localStorage.getItem("token");

    this.setState({
      loadingTypesBrands: true,
    });

    fetch("https://iranaserviceapp.ir/test/api/list-type", {
      method: "GET",
      headers: {
        Accept: "application/json",
        ...(token
          ? {
              Authorization: `Bearer ${token}`,
            }
          : {}),
      },
    })
      .then((response) => response.json())
      .then((data) => {
        if (data.status === "1") {
          this.setState({
            types: data.types || [],
            brands: data.brands || [],
            loadingTypesBrands: false,
          });
        } else {
          this.setState({
            loadingTypesBrands: false,
          });
        }
      })
      .catch((error) => {
        console.error("loadTypesBrands error:", error);

        this.setState({
          loadingTypesBrands: false,
        });
      });
  }

  validateMobile(mobile) {
    const cleanMobile = mobile.replace(/\D/g, "");

    return /^09\d{9}$/.test(cleanMobile);
  }

  handleSubmit(e) {
    e.preventDefault();

    const {
      fullName,
      mobile,
      landline,
      province,
      city,
      address,
      deviceType,
      deviceBrand,
      deviceIssue,
      visitTime,
      description,
    } = this.state;

    if (!fullName.trim()) {
      alert("نام کامل را وارد کنید");
      return;
    }

    if (!mobile.trim()) {
      alert("شماره موبایل را وارد کنید");
      return;
    }

    if (!this.validateMobile(mobile)) {
      alert("شماره موبایل صحیح نیست");
      return;
    }

    if (!province) {
      alert("استان را انتخاب کنید");
      return;
    }

    if (!city) {
      alert("شهر را انتخاب کنید");
      return;
    }

    if (!address.trim()) {
      alert("آدرس را وارد کنید");
      return;
    }

    if (!deviceType) {
      alert("نوع دستگاه را انتخاب کنید");
      return;
    }

    if (!deviceBrand) {
      alert("برند دستگاه را انتخاب کنید");
      return;
    }

    if (!deviceIssue.trim()) {
      alert("ایراد دستگاه را وارد کنید");
      return;
    }

    if (!visitTime) {
      alert("زمان مراجعه را انتخاب کنید");
      return;
    }

    const token = localStorage.getItem("token");

    if (!token) {
      alert("توکن ورود پیدا نشد");
      return;
    }

    /*
     * visitTime به صورت شمسی مثل:
     * 1405/06/10
     *
     * تبدیل به میلادی:
     * 2026/09/01
     */

    const gregorianDate = moment(
      visitTime,
      "jYYYY/jMM/jDD"
    ).format("YYYY/MM/DD");

    this.setState({
      submitting: true,
    });

    fetch("https://iranaserviceapp.ir/test/api/create", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Accept: "application/json",
        Authorization: `Bearer ${token}`,
      },
      body: JSON.stringify({
        name: fullName,
        mobile: mobile,
        mobile2: landline,

        state: province,
        city: city,

        device_brand: deviceBrand,
        device_type: deviceType,

        address: address,

        problem: deviceIssue,
        description: description,

        time: gregorianDate,
      }),
    })
      .then((response) => response.json())
      .then((data) => {
        this.setState({
          submitting: false,
        });

        if (data.status === "1") {
          alert(data.message || "درخواست با موفقیت ثبت شد");

          this.setState({
            fullName: "",
            mobile: "",
            landline: "",

            province: "",
            city: "",
            address: "",

            deviceType: "",
            deviceBrand: "",

            deviceIssue: "",
            visitTime: "",
            description: "",

            cities: [],
          });
        } else {
          alert(data.message || "ثبت درخواست انجام نشد");
        }
      })
      .catch((error) => {
        console.error("create request error:", error);

        this.setState({
          submitting: false,
        });

        alert("خطا در ارتباط با سرور");
      });
  }

  render() {
    const {
      fullName,
      mobile,
      landline,
      province,
      city,
      address,
      deviceType,
      deviceBrand,
      deviceIssue,
      visitTime,
      description,

      states,
      cities,
      types,
      brands,

      loadingStates,
      loadingCities,
      loadingTypesBrands,
      submitting,
    } = this.state;

    return (
      <div className="container pt-3">
        <div
          className="mx-auto"
          style={{ maxWidth: "480px" }}
        >
          <h6 className="text-center fw-bold text-dark mb-4">
            اطلاعات مشتری را با دقت ثبت کنید
          </h6>

          <form onSubmit={this.handleSubmit}>

            {/* نام کامل */}
            <div className="custom-input mb-3">
              <div className="custom-icon">
                <FaUser />
              </div>

              <input
                type="text"
                placeholder="نام کامل"
                value={fullName}
                onChange={this.handleChange("fullName")}
              />
            </div>

            {/* شماره موبایل */}
            <div className="custom-input mb-3">
              <div className="custom-icon">
                <FaPhone />
              </div>

              <input
                type="tel"
                inputMode="numeric"
                placeholder="شماره موبایل"
                value={mobile}
                onChange={this.handleChange("mobile")}
              />
            </div>

            {/* تلفن ثابت */}
            <div className="custom-input mb-3">
              <div className="custom-icon">
                <FaPhone />
              </div>

              <input
                type="tel"
                inputMode="numeric"
                placeholder="تلفن ثابت"
                value={landline}
                onChange={this.handleChange("landline")}
              />
            </div>

            {/* استان */}
            <div className="custom-input mb-3">
              <div className="custom-icon">
                <FaMapMarkerAlt />
              </div>

              <select
                value={province}
                onChange={this.handleChange("province")}
                disabled={loadingStates}
              >
                <option value="" disabled>
                  {loadingStates
                    ? "در حال دریافت استان‌ها..."
                    : "استان"}
                </option>

                {states.map((state) => (
                  <option
                    key={state.id}
                    value={state.id}
                  >
                    {state.name}
                  </option>
                ))}
              </select>
            </div>

            {/* شهر */}
            <div className="custom-input mb-3">
              <div className="custom-icon">
                <FaMapMarkerAlt />
              </div>

              <select
                value={city}
                onChange={this.handleChange("city")}
                disabled={!province || loadingCities}
              >
                <option value="" disabled>
                  {!province
                    ? "ابتدا استان را انتخاب کنید"
                    : loadingCities
                    ? "در حال دریافت شهرها..."
                    : "شهر"}
                </option>

                {cities.map((item) => (
                  <option
                    key={item.id}
                    value={item.id}
                  >
                    {item.name}
                  </option>
                ))}
              </select>
            </div>

            {/* آدرس */}
            <div className="custom-input mb-3">
              <div className="custom-icon">
                <FaMapMarkerAlt />
              </div>

              <input
                type="text"
                placeholder="آدرس"
                value={address}
                onChange={this.handleChange("address")}
              />
            </div>

            {/* نوع دستگاه */}
            <div className="custom-input mb-3">
              <div className="custom-icon">
                <FaImage />
              </div>

              <select
                value={deviceType}
                onChange={this.handleChange("deviceType")}
                disabled={loadingTypesBrands}
              >
                <option value="" disabled>
                  {loadingTypesBrands
                    ? "در حال دریافت..."
                    : "نوع دستگاه"}
                </option>

                {types.map((type) => (
                  <option
                    key={type.id}
                    value={type.id}
                  >
                    {type.name}
                  </option>
                ))}
              </select>
            </div>

            {/* برند دستگاه */}
            <div className="custom-input mb-3">
              <div className="custom-icon">
                <FaTag />
              </div>

              <select
                value={deviceBrand}
                onChange={this.handleChange("deviceBrand")}
                disabled={loadingTypesBrands}
              >
                <option value="" disabled>
                  {loadingTypesBrands
                    ? "در حال دریافت..."
                    : "برند دستگاه"}
                </option>

                {brands.map((brand) => (
                  <option
                    key={brand.id}
                    value={brand.id}
                  >
                    {brand.name}
                  </option>
                ))}
              </select>
            </div>

            {/* ایراد دستگاه */}
            <div className="custom-input mb-3">
              <div className="custom-icon">
                <FaQuestionCircle />
              </div>

              <input
                type="text"
                placeholder="ایراد دستگاه"
                value={deviceIssue}
                onChange={this.handleChange("deviceIssue")}
              />
            </div>

            {/* زمان مراجعه */}
            <div className="custom-input mb-3">
              <div className="custom-icon">
                <FaClock />
              </div>

              <input
                type="text"
                placeholder="زمان مراجعه"
                value={visitTime}
                onChange={this.handleChange("visitTime")}
                onFocus={(e) => {
                  e.target.type = "date";
                }}
                onBlur={(e) => {
                  if (!e.target.value) {
                    e.target.type = "text";
                  }
                }}
              />
            </div>

            {/* توضیحات */}
            <div className="custom-input mb-3">
              <div className="custom-icon">
                <FaLink />
              </div>

              <input
                type="text"
                placeholder="توضیحات"
                value={description}
                onChange={this.handleChange("description")}
              />
            </div>

            {/* دکمه */}
            <button
              type="submit"
              className="btn btn-sub w-100 fw-bold py-2 rounded-4"
              disabled={submitting}
            >
              <small>
                {submitting
                  ? "در حال ثبت..."
                  : "ثبت درخواست"}
              </small>
            </button>

          </form>
        </div>
      </div>
    );
  }
}

export default CustomerRequestForm;
